import "./Reviews.css";

export default function Reviews() {
const reviews = [
{ text: "Amazing service! Highly recommended.", author: "Rohan" },
{ text: "The team was very professional and prompt.", author: "Priya" },
{ text: "Affordable prices and excellent quality.", author: "Arjun" },
{ text: "I am very satisfied with their service. Will come back again.", author: "Sneha" },
{ text: "Quick response and friendly staff. Loved it!", author: "Vikram" }
];

return ( <div className="page"> <h1>Customer Reviews</h1>
{reviews.map((review, index) => ( <div key={index} className="review-box"> <p>"{review.text}"</p> <span>- {review.author}</span> </div>
))} </div>
);
}
